CREATE TABLE prj24_report_orders (order_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, order_status TEXT NOT NULL);
CREATE TABLE prj24_report_items (item_id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL, quantity INTEGER NOT NULL, unit_price INTEGER NOT NULL);
INSERT INTO prj24_report_orders VALUES (101, 'Asha', 'paid'), (102, 'Bilal', 'paid');
INSERT INTO prj24_report_items VALUES (1, 101, 2, 250), (2, 101, 1, 60), (3, 102, 1, 400);
SELECT o.customer_name, SUM(i.quantity * i.unit_price) AS revenue FROM prj24_report_orders o JOIN prj24_report_items i ON i.order_id=o.order_id GROUP BY o.customer_name ORDER BY revenue DESC;

